const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const sourcePayload = $json.source_payload_json ?? {};
const creativeDefaults = sourcePayload.creative_defaults && typeof sourcePayload.creative_defaults === 'object'
  ? sourcePayload.creative_defaults
  : {};
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const narrationScript = String($json.narration_script ?? '').trim();
const sceneGuidanceJson = Array.isArray($json.scene_guidance_json) ? $json.scene_guidance_json : [];
const queueQueryReturnedNoCandidate = String($json.success ?? '').trim().toLowerCase() === 'true'
  && !contentId
  && !title;
if (queueQueryReturnedNoCandidate) {
  throw new Error('No script_complete content item is currently available for wf_director_contract.');
}
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Script Complete Item did not atomically claim a valid content_id: ' + (contentId || '<empty>') + '.');
}
if (!title) {
  throw new Error('Fetch Next Script Complete Item did not return title.');
}
if (!narrationScript) {
  throw new Error('Fetch Next Script Complete Item did not return narration_script.');
}
if (sceneGuidanceJson.length < 4) {
  throw new Error('Director contract requires at least 4 scenes in scene_guidance_json. Got ' + sceneGuidanceJson.length + '.');
}
const targetDurationSeconds = Number($json.target_duration_seconds ?? 45);
if (!Number.isFinite(targetDurationSeconds) || targetDurationSeconds <= 0) {
  throw new Error('target_duration_seconds must be a positive number.');
}
const promptPayload = {
  content_id: contentId,
  title,
  target_duration_seconds: targetDurationSeconds,
  status_after_success: 'directed',
  prompt_template_data: {
    title,
    category: String($json.category ?? 'general').trim() || 'general',
    target_duration_seconds: String(targetDurationSeconds),
    narration_script: narrationScript,
    scene_guidance_json: sceneGuidanceJson,
    scene_count: String(sceneGuidanceJson.length),
    creative_defaults: creativeDefaults,
    creative_defaults_json: Object.keys(creativeDefaults).length > 0 ? JSON.stringify(creativeDefaults, null, 2) : '{}',
  },
};
return [{
  json: {
    ...promptPayload,
    prompt_payload_base64: Buffer.from(JSON.stringify(promptPayload), 'utf8').toString('base64')
  }
}];

const stdout = String($json.stdout ?? '').trim();
if (!stdout) {
  throw new Error('Director contract adapter returned no stdout.');
}
let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (error) {
  throw new Error('Director contract adapter returned invalid JSON: ' + error.message);
}
if (!parsed.content_id || !parsed.director_contract_response) {
  throw new Error('Director contract adapter did not provide content_id or director_contract_response.');
}
return [{ json: parsed }];

const response = $json.director_contract_response ?? {};
if (!$json.content_id) {
  throw new Error('Director contract adapter did not provide content_id.');
}
for (const field of ['voice_role', 'tts_delivery', 'global_visual_style', 'visual_strategy', 'global_pacing', 'energy_curve', 'mood_curve', 'global_music_direction']) {
  if (!String(response[field] ?? '').trim()) {
    throw new Error('Director contract adapter did not return ' + field + '.');
  }
}
if (!Array.isArray(response.scenes) || response.scenes.length < 4) {
  throw new Error('Director contract adapter must return at least 4 scenes. Got: ' + (Array.isArray(response.scenes) ? response.scenes.length : 0) + '.');
}
for (const scene of response.scenes) {
  if (!scene.tts_instructions) {
    throw new Error('Director contract scene ' + scene.scene_number + ' is missing tts_instructions.');
  }
  if (!scene.visual_strategy) {
    throw new Error('Director contract scene ' + scene.scene_number + ' is missing visual_strategy.');
  }
}
return [{
  json: {
    ...$json,
    director_json: response,
    voice_role: String(response.voice_role || '').trim(),
    tts_delivery: String(response.tts_delivery || '').trim(),
    global_visual_style: String(response.global_visual_style || '').trim(),
    visual_strategy: String(response.visual_strategy || '').trim(),
    global_pacing: String(response.global_pacing || '').trim(),
    global_music_direction: String(response.global_music_direction || '').trim(),
    scene_count: response.scenes.length,
  }
}];

const cost_json_sql = JSON.stringify($json.cost ?? {}).replaceAll("'", "''");
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare Director Contract SQL Values received invalid content_id: ' + (contentId || '<empty>') + '.');
}
const directorJson = $json.director_json ?? {};
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    voice_role_sql: String(directorJson.voice_role ?? '').replaceAll("'", "''"),
    tts_delivery_sql: String(directorJson.tts_delivery ?? '').replaceAll("'", "''"),
    global_visual_style_sql: String(directorJson.global_visual_style ?? '').replaceAll("'", "''"),
    visual_strategy_sql: String(directorJson.visual_strategy ?? '').replaceAll("'", "''"),
    global_pacing_sql: String(directorJson.global_pacing ?? '').replaceAll("'", "''"),
    global_music_direction_sql: String(directorJson.global_music_direction ?? '').replaceAll("'", "''"),
    director_json_sql: JSON.stringify(directorJson).replaceAll("'", "''"),
    generation_model_sql: String($json.generation_model ?? '').replaceAll("'", "''"),
    workflow_name_sql: 'wf_director_contract',
    scene_count_sql: Number($json.scene_count ?? 0),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0,
    cost_json_sql,
  }
}];
